// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(bytes32 guess1, bytes32 guess2, address actor) public {
        vm.assume(actor != address(0));
        vm.deal(actor, 2 ether);

        // first lock-in
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess1);

        // a second lock-in must revert: the guess is already locked
        vm.prank(actor);
        bool ok;
        try c.lockInGuess{value: 1 ether}(guess2) { ok = true; } catch { ok = false; }

        assertTrue(!ok, "re-locking must revert");
    }
}
